#!ibl edition=2
$sv = [limbs:browser]{op:"click", ref:"e7"}
$w = [limbs:browser]{op:"wait", text:"저장됨"}
$c = [limbs:browser]{op:"content", mode:"text"}
$cl = [limbs:browser]{op:"tab", mode:"close"}
$tabs = [limbs:browser]{op:"tab", mode:"list"}
$n = [limbs:browser]{op:"navigate", url:"http://127.0.0.1:8989/display", wait:"load"}
$s = [limbs:browser]{op:"snapshot"}
$items = $s.snapshot >> [table:filter]{where:($e)=>contains($e.name,"진열 항목")}
$src = filter($items, ($e)=>contains($e.name,"유리 화병 대"))[0]
$dst = filter($items, ($e)=>contains($e.name,"황동 촛대"))[0]
$d = [limbs:browser]{op:"drag", source_ref:$src.ref, target_ref:$dst.ref}
$o = [limbs:browser]{op:"evaluate", expression:"[...document.querySelectorAll('#list li')].map(li=>li.dataset.id).join(',') + ' | ' + document.getElementById('st').textContent"}
return {wait:$w, text:$c.text, close:$cl, tabs:$tabs.tabs, items:$items, drag:$d, order:$o.result}
